import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"47、【困】 坎下兌上","description":"周易闡真 - 47、【困】 坎下兌上","frontmatter":{"title":"47、【困】 坎下兌上","description":"周易闡真 - 47、【困】 坎下兌上"},"headers":[],"relativePath":"classics/chanzhen/048.md","filePath":"classics/chanzhen/048.md"}'),s={name:"classics/chanzhen/048.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：困，剛揜也。險以說，困而不失其所亨，其唯君子乎！貞大人吉，以剛中也。有言不信，尚口乃窮也。</p></blockquote><h1 id="_47、【困】-坎下兌上" tabindex="-1">47、【困】 坎下兌上 <a class="header-anchor" href="#_47、【困】-坎下兌上" aria-label="Permalink to “47、【困】 坎下兌上”">​</a></h1><p>初六：臀困於株木，入於幽谷，三歲不覿。</p><p>九二：困於酒食，朱紱方來，利用亨祀。徵兇，無咎。</p><p>六三：困於石，據於蒺藜，入於其宮，不見其妻，兇。</p><p>九四：來徐徐，困於金車，吝，有終。</p><p>九五：劓刖，困於赤紱，乃徐有說，利用祭祀。</p><p>上六：困於葛藟，於臲危副本，曰動悔。有悔，徵吉。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：澤無水，困。君子以致命遂志。</p><p>困者，窮也。上兌澤，下坎水，是澤漏水流，澤中無水，困之象也。</p><p>君子有見於此，知澤無水，則澤空；人無志，則道窮。以是致命而遂其志焉。致者，極也。命有氣數之命，有道義之命。氣數之命，天地所造，後天也；道義之命，造乎天地，先天也。先天之命，本是乾家之物，因交後天，入於坤宮，化而為坎，坎中一陽是也。此陽一陷，命寶潛藏，一身純陰，困莫困於此矣。致命者，極其後天之命；遂志者，遂其先天之命。立志以致命，致命以遂志，氣數在彼，造命在我，借後天，返先天，盡假命，立真命，無中生有，殺中求生，由困而通；亦如澤中無水，而又有水。卦象兌金自坎水而出，只取水中金一味者，亦不在此乎?</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>紱，音弗。刖，音月。說，音悅。臲，音業。危副本，音兀。</p><p>困者，窮難也。卦體下坎，一陽陷於二陰之中，上兌，一陰居於二陽之上，均系陰浸其陽，陽氣不通之象，故謂困。卦德險中出悅，悅出於險，兼有濟困之義。此磨礪身心之卦，承上萃卦而來。萃者，由順得悅，所以攢簇藥物，返本還元也。但能攢簇於平易，不能攢簇於艱險，仍是不能順、不能悅。特以修道者平易之境，皆能有守，艱險之地，每多變志，或為衣食逼迫改唸，或因疾病纏綿墮志，或因年老灰心，或因魔障歇工，諸如此類，皆是道心不力，為困所拘，終不成道。若果身困而心不困，境困而道不困，處險能悅，困中反有亨道矣。</p><p>雖然處險能悅，因為人所不及，亦必困所當困，若困所不當困，亦不得亨。蓋困之亨道，在於得其正耳。以正處困，以正而亨，困而與時偕行也。與時偕行，惟俱中正之德之大人能之。特以大人者，大智若愚，大巧若拙，諸念不生，遇境難遷，素位而行，不願乎外，不但所處得其吉，而且順命能無咎。至於一切衣食之徒，不信於困，行險僥倖，稍不如意，形於辭色，怨天尤人，咎即隨之，何能致吉?以正處困，險而能悅，則為大人；困而不信，悅以行險，則為小人。同一險也，同一悅也，而大人小人分之。修道者，遇困可不守其正乎?</p><p>初六，在困之初，其困不大，又近二陽，不宜受困，乃柔弱無剛，自暴自棄，甘居人下，如臀困於株,木入於幽谷矣。如此之人，不當困而困，雖三歲之久，終不能出險。此小困而自致大困者也。</p><p>九二，陽陷陰中，正在衣祿不足之時，如困於酒食也。幸其剛而得中，為道忘軀，身困而心不困，一日苦盡甜生，大道完成，方且服天衣、食天祿，如朱紱方來，修天爵而人爵即從之，先困後亨，理有可必。先困後亨之象，其利如用亨祀，以誠格天，久而見功，若正在困中，急欲出困，反招其兇，亦無咎，其困而不亨矣。此先困而後得亨者也。</p><p>六三，愚而自用，不知尊師敬友，為正人君子所嫌惡，如困於石，據於蒺藜，自入於困矣。如此之人，本無實學，自負有道，務外失內，亦如入於其宮，不見其妻，終亦必亡而已。此無困而自致困者也。</p><p>九四，出險地而居悅體，正當濟困之時，乃剛居於柔，不能速濟，似乎以柔傷剛，來徐徐如困於金章，而有吝道矣。然在困已久，不能直行其道，徐徐而來，終有如意之時。此有困而漸濟困者也。</p><p>九五，陽剛中正，遇合不偶，有大作之道，而無大作之時，難行法財兩用之事，不能隨心所欲，如劓鼻刖足，赤紱受困。此抱道者之大困也。既在困中，未可強求於外，須當被褐懷玉，自苦自力，乃徐有悅也。徐悅之利，如用祭祀，以誠而入，日久功深，自有完成大道之時。此信困而漸出困者也。</p><p>上六，昏愚無知，自作聰明，妄猜私議，如葛藟挪扯，穿鑿聖道，自謂得真，即便扭捏，日久受害，向前不得，退後不能，臲危副本 困危，是曰動悔。與其動而有悔，不若及早自悔，尋師訪友，明而後行，始雖入於旁門，而受困致悔，終必聞乎大道，而徵往得吉。此有悔而終出困者也。</p><p>六爻之用，有大人之困，有小人之困。大人之困，處險能悅，信其困而終無咎；小人之困，悅以行險，不信困而終有悔。困而致亨之道，險而能悅，待時守正，盡之矣。</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
